d=Document();d.styles['Normal'].font.name='Calibri';d.styles['Normal'].font.size=Pt(10);d.sections[0].header.paragraphs[0].text='SHIVANSH / ONGC BRRP | INTEGRATED PROJECT PACKAGE P5 | FOR REVIEW'
